-- Cook Torka uses the same cooking list as Duhng
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`CreatureID` int unsigned NOT NULL, `TrainerID` int unsigned NOT NULL, `MenuID` int unsigned NOT NULL, `OptionID` int unsigned NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`CreatureID`, `MenuID`, `OptionID`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `everlake_import_stage` (`CreatureID`, `TrainerID`, `MenuID`, `OptionID`, `note`) VALUES
(3191, 36, 5854, 0, 'EG Link live 70790/70840 Cook Torka and 70862 Duhng; matching menu and lessons');
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `creature_trainer` t WHERE t.`CreatureID` = s.`CreatureID` AND t.`MenuID` = s.`MenuID` AND t.`OptionID` = s.`OptionID`) AND EXISTS (SELECT 1 FROM `creature_template` WHERE `entry` = 3191 AND `npcflag` = 2 AND `VerifiedBuild` = 69497)
AND EXISTS (SELECT 1 FROM `creature` WHERE `id` = 3191 AND `npcflag` IS NULL)
AND EXISTS (SELECT 1 FROM `creature_template_gossip` WHERE `CreatureID` = 3191 AND `MenuID` = 5854)
AND EXISTS (SELECT 1 FROM `gossip_menu_option` WHERE `MenuID` = 5854 AND `OptionID` = 0 AND `OptionNpc` = 3)
AND EXISTS (SELECT 1 FROM `creature_trainer` WHERE `CreatureID` = 8306 AND `TrainerID` = 36 AND `MenuID` = 5854 AND `OptionID` = 0)
AND EXISTS (SELECT 1 FROM `trainer` WHERE `Id` = 36 AND `Type` = 2)
AND (SELECT COUNT(*) FROM `trainer_spell` WHERE `TrainerId` = 36) = 10
AND NOT EXISTS (SELECT 1 FROM `trainer_spell` WHERE `TrainerId` = 36
                AND `SpellId` NOT IN (2539,2541,2544,2546,2551,3412,6499,6500,21175,1229737))
AND NOT EXISTS (SELECT 1 FROM `creature_trainer` WHERE `CreatureID` = 3191)
AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` WHERE `tbl` = 'creature_trainer' AND `k1` = 3191);
INSERT INTO `creature_trainer` (`CreatureID`, `TrainerID`, `MenuID`, `OptionID`) SELECT `CreatureID`, `TrainerID`, `MenuID`, `OptionID` FROM `everlake_import_stage` WHERE `missing` = 1;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `k2`, `k3`, `file`, `note`) SELECT 'creature_trainer', s.`CreatureID`, s.`MenuID`, s.`OptionID`, '2026_11_10_06_world_everlake_import_slice11.sql', s.`note` FROM `everlake_import_stage` s WHERE s.`missing` = 1 ON DUPLICATE KEY UPDATE `file` = '2026_11_10_06_world_everlake_import_slice11.sql', `note` = s.`note`;
